import{_ as a,c as t,o as i,a9 as l}from"./chunks/framework.Bqk8xQPS.js";const m=JSON.parse('{"title":"AI agents","description":"Build PURISTA agents through one clear flow: define, implement, create an instance, then adapt at the SDK boundary.","frontmatter":{"title":"AI agents","description":"Build PURISTA agents through one clear flow: define, implement, create an instance, then adapt at the SDK boundary.","order":203700},"headers":[],"relativePath":"handbook/2_building_business-logic/agent/index.md","filePath":"handbook/2_building_business-logic/agent/index.md","lastUpdated":1774341903000}'),n={name:"handbook/2_building_business-logic/agent/index.md"};function o(r,e,s,d,h,c){return i(),t("div",null,[...e[0]||(e[0]=[l(`<h1 id="ai-agents" tabindex="-1">AI agents <a class="header-anchor" href="#ai-agents" aria-label="Permalink to “AI agents”">​</a></h1><p><code>@purista/ai</code> should be understood in the same way as the rest of PURISTA:</p><ol><li>define the workload with a builder</li><li>implement the business logic in the handler</li><li>create an instance with real runtime dependencies</li><li>adapt only at the transport or SDK boundary</li></ol><p>This handbook section is organized around that exact flow.</p><h2 id="the-mental-model" tabindex="-1">The Mental Model <a class="header-anchor" href="#the-mental-model" aria-label="Permalink to “The Mental Model”">​</a></h2><ul><li><code>AgentBuilder</code> defines what the agent is allowed to do.</li><li>The handler uses <code>context</code> to call models, commands, child agents, stores, skills, and streaming.</li><li><code>getInstance(...)</code> binds the definition to real models, stores, queues, skills, and sandbox execution.</li><li>Adapters such as the Vercel AI SDK integration sit at the edge. They do not own your business logic.</li></ul><p>If you keep those boundaries clean, the API becomes much easier to understand.</p><h2 id="the-canonical-flow" tabindex="-1">The Canonical Flow <a class="header-anchor" href="#the-canonical-flow" aria-label="Permalink to “The Canonical Flow”">​</a></h2><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[&quot;1. Define with AgentBuilder&quot;] --&gt; B[&quot;2. Implement in handler(context, payload)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt; C[&quot;3. Create instance with getInstance(eventBridge, options)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; D[&quot;4. Adapt at HTTP / SSE / AI SDK boundary&quot;]</span></span></code></pre></div><p>The most important rule is: do not jump straight into SDK adapters or sandbox details before the first three steps are clear.</p><h2 id="one-running-example" tabindex="-1">One Running Example <a class="header-anchor" href="#one-running-example" aria-label="Permalink to “One Running Example”">​</a></h2><p>Across the pages below, the same example is used repeatedly:</p><ul><li>a queued durable <code>supportAgent</code></li><li>one inline <code>triageAgent</code></li><li>one allowlisted command <code>support.1.lookupFaq</code></li><li>one allowlisted child agent <code>triageAgent.1</code></li><li>two declared skills: <ul><li><code>spec-elicitation</code></li><li><code>support-workflow</code></li></ul></li></ul><p>That example is intentionally small, but it exercises the main PURISTA concerns:</p><ul><li>builder declaration</li><li>handler logic</li><li>typed instance creation</li><li>skills</li><li>streaming</li><li>queued durable execution</li><li>model-provider adapter usage</li></ul><h2 id="what-each-page-answers" tabindex="-1">What Each Page Answers <a class="header-anchor" href="#what-each-page-answers" aria-label="Permalink to “What Each Page Answers”">​</a></h2><h3 id="_1-define" tabindex="-1">1. Define <a class="header-anchor" href="#_1-define" aria-label="Permalink to “1. Define”">​</a></h3><ul><li><a href="./getting-started.html">Quick Start</a> Builds one complete working agent path end to end.</li><li><a href="./agent-builder.html">Builder</a> Explains what belongs in <code>AgentBuilder</code> and what does not.</li><li><a href="./skills.html">Skills</a> Shows how to define skills and declare them in the builder.</li></ul><h3 id="_2-implement" tabindex="-1">2. Implement <a class="header-anchor" href="#_2-implement" aria-label="Permalink to “2. Implement”">​</a></h3><ul><li><a href="./handler-context.html">Context</a> Explains what the handler gets and how to use it.</li><li><a href="./production-ready-agents.html">Production-Ready Agents</a> Shows how reflection, approvals, durable state, and trajectory testing fit together in one real example.</li><li><a href="./run-state.html">Durable Run State</a> Focuses on plans, tasks, checkpoints, locks, and recovery.</li><li><a href="./invocation.html">Invocation</a> Covers child-agent orchestration and agent-to-agent calls.</li></ul><h3 id="_3-create-the-instance" tabindex="-1">3. Create The Instance <a class="header-anchor" href="#_3-create-the-instance" aria-label="Permalink to “3. Create The Instance”">​</a></h3><ul><li><a href="./runtime.html">Runtime</a> Shows what belongs in <code>getInstance(...)</code>: models, skills, stores, queue bridges, pools, and sandbox runtime.</li><li><a href="./memory-and-retrieval.html">Memory &amp; Retrieval</a> Clarifies conversation memory, retrieval, and durable run state boundaries.</li></ul><h3 id="_4-adapt" tabindex="-1">4. Adapt <a class="header-anchor" href="#_4-adapt" aria-label="Permalink to “4. Adapt”">​</a></h3><ul><li><a href="./ai-sdk-adapter.html">AI SDK Adapter</a> Explains how to adapt PURISTA bindings and skills to the Vercel AI SDK.</li><li><a href="./external-runtime-bridge.html">External Runtime Bindings</a> Describes the provider-neutral binding layer.</li><li><a href="./frontend.html">Web &amp; SDK</a> Covers HTTP/SSE transport and frontend streaming.</li><li><a href="./../../3_eco_system/sandbox.html">Sandbox Runtime</a> Covers isolated repo and skill execution when the agent needs a real workspace.</li></ul><h2 id="decision-rules" tabindex="-1">Decision Rules <a class="header-anchor" href="#decision-rules" aria-label="Permalink to “Decision Rules”">​</a></h2><ul><li>Start with <a href="./getting-started.html">Quick Start</a> if you want a full working path.</li><li>Start with <a href="./agent-builder.html">Builder</a> if you are designing the contract of an agent.</li><li>Start with <a href="./handler-context.html">Context</a> if you already have a builder and need to implement behavior.</li><li>Start with <a href="./runtime.html">Runtime</a> if the main question is how to bootstrap the agent in production.</li><li>Start with <a href="./ai-sdk-adapter.html">AI SDK Adapter</a> only when the model/tool loop will run through Vercel AI SDK.</li></ul><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to “Common Mistakes”">​</a></h2><ul><li>Treating agents as “just prompts” instead of normal PURISTA workloads with explicit dependencies.</li><li>Mixing builder-time declaration with runtime provisioning.</li><li>Loading tools or skills implicitly instead of declaring them and providing them at <code>getInstance(...)</code>.</li><li>Starting with SDK adapters before the core PURISTA flow is implemented.</li></ul><h2 id="what-to-read-next" tabindex="-1">What To Read Next <a class="header-anchor" href="#what-to-read-next" aria-label="Permalink to “What To Read Next”">​</a></h2><p>If you want one coherent walkthrough, read in this order:</p><ol><li><a href="./getting-started.html">Quick Start</a></li><li><a href="./agent-builder.html">Builder</a></li><li><a href="./handler-context.html">Context</a></li><li><a href="./runtime.html">Runtime</a></li><li><a href="./skills.html">Skills</a></li><li><a href="./ai-sdk-adapter.html">AI SDK Adapter</a></li></ol>`,31)])])}const p=a(n,[["render",o]]);export{m as __pageData,p as default};
